/* ---------------- stations (space journey) ---------------- */
var STATIONS = [{f:0,e:'🌍',a:'الأرض',d:'منصة الإطلاق'},{f:.104,e:'☁️',a:'فوق السحاب',d:'أول خطوة'},{f:.208,e:'🛰️',a:'المدار',d:'بدأت الرحلة فعلا'},
  {f:.333,e:'🌙',a:'القمر',d:'أساس قوي'},{f:.479,e:'🔴',a:'المريخ',d:'نصف الطريق تقريبا'},{f:.645,e:'🟠',a:'المشتري',d:'مستوى رائع'},{f:.833,e:'🪐',a:'زحل',d:'قريب جدا من النهاية'},{f:1,e:'🌌',a:'المجرة',d:'أكملت كل شيء!'}];
function stNeed(i){ return Math.ceil(STATIONS[i].f * UNITS.length); }
function stationIdx(){ var n = doneCount(), r = 0; STATIONS.forEach(function(s, i){ if (n >= stNeed(i)) r = i; }); return Math.max(r, S.stFloor || 0); }
function station(){ return STATIONS[stationIdx()]; }
var pendingSt = false;
function checkStation(){
  var i = stationIdx(); if (i <= (S.station || 0)) return;
  if (($('#stage') && !$('.result')) || $('.modal') || $('.stfx')){ pendingSt = true; return; }
  pendingSt = false;
  S.station = i; save(); var st = STATIONS[i];
  stationFX(i, st);
}
/* full screen scene when a new station is reached */
function stationFX(i, st){
  var ov = document.createElement('div'); ov.className = 'stfx'; ov.setAttribute('role', 'dialog'); ov.setAttribute('aria-label', 'وصلت إلى ' + st.a);
  ov.innerHTML = '<div class="stfx3 j3d" id="stfx3"></div><div class="stfxt"><small>وصلت إلى</small><div class="stfxe">' + uiPic('st' + i, st.e) + '</div><h2>' + st.a + '</h2></div>' +
    '<div class="stfxb"><button class="btn wide flame" id="stGo">كمل الرحلة</button><button class="stfxs" id="stSh">شارك إنجازك</button></div>';
  document.body.appendChild(ov); document.documentElement.classList.add('stfxon');
  var close = function(){ var g = gs(); document.documentElement.classList.remove('stfxon'); removeEventListener("keydown", onKey);
    if (g) g.to(ov, {opacity:0, duration:.35, onComplete:function(){ ov.remove(); }}); else ov.remove(); };
  var onKey = function(e){ if (e.key === "Escape") close(); }; addEventListener("keydown", onKey);
  $('#stGo', ov).onclick = close; $('#stSh', ov).onclick = function(){ close(); shareBadge(); };
  var shown = false, reveal = function(){ if (shown || !document.body.contains(ov)) return; shown = true; ov.classList.add('arr'); confetti();
    var g = gs(); if (g){ g.fromTo($('.stfxt', ov), {opacity:0, y:24, scale:.9}, {opacity:1, y:0, scale:1, duration:.7, ease:'back.out(1.8)'}); g.fromTo($('.stfxb', ov), {opacity:0, y:20}, {opacity:1, y:0, duration:.5, delay:.35}); } };
  var g0 = gs(); if (g0) g0.fromTo(ov, {opacity:0}, {opacity:1, duration:.4});
  if (calm()) return reveal();
  journey3D($('#stfx3', ov), i, 0, {from:Math.max(0, (i - 1) / (STATIONS.length - 1)), fx:true, onArrive:reveal});
  setTimeout(reveal, 4200);
}

