function lenaWelcome(next){
  if ($('.modal')) return;
  var L = [[0, 'Hallo!', 'أهلا!'], [0.9, 'Willkommen bei Sprachrakete!', 'مرحبا بك في Sprachrakete!'], [2.75, 'Lass uns zusammen Deutsch lernen – Schritt für Schritt!', 'هيا نتعلم الألمانية معا، خطوة بخطوة!']];
  var m = modal('<div class="ln-st">' + LW_SVG + '</div><div class="ln-cap" id="lnCap"><div class="de">Hallo! 👋</div><div class="ar">أنا لينا، اضغط لتسمعني</div></div><button class="btn wide" id="lnPlay">▶ استمع إلى لينا</button><button class="linkbtn" id="lnSkip">تخط</button>', 'lncard');
  var au = new Audio('lena.mp3'), raf, cur = -1, done = 0, mo = $('#ln-mo', m), sm = $('#ln-sm', m), cap = $('#lnCap', m), pb = $('#lnPlay', m);
  au.preload = 'auto';
  function close(){ try{ au.pause(); }catch(e){} cancelAnimationFrame(raf); S.lena = 1; save(); m.remove(); if (next) setTimeout(next, 300); }
  m.querySelector('.x').onclick = close; m.onclick = function(e){ if (e.target === m) close(); }; $('#lnSkip', m).onclick = close;
  function mouth(v){ mo.setAttribute('transform', 'translate(150 186) scale(1 ' + v.toFixed(2) + ')'); sm.style.opacity = v > .15 ? 0 : 1; }
  function setCap(a, b){ cap.innerHTML = '<div class="de">' + a + '</div><div class="ar">' + b + '</div>'; }
  function loop(){ var t = au.currentTime, ph = t % 1, v = au.paused ? 0 : Math.max(0, .15 + .75 * Math.abs(Math.sin(t * 11)));
    var gap = t < 0.18 || (t > 0.63 && t < 1.03) || (t > 2.57 && t < 2.98) || t > 5.36; mouth(gap || v < .12 ? 0 : v);
    for (var k = L.length - 1; k >= 0; k--){ if (t >= L[k][0]){ if (cur !== k){ cur = k; setCap(L[k][1], L[k][2]); } break; } }
    if (!au.paused && !au.ended) raf = requestAnimationFrame(loop); else mouth(0); }
  au.onended = function(){ mouth(0); done = 1; var sv = $('.lnsvg2', m); if (sv){ sv.classList.add('yay'); setTimeout(function(){ sv.classList.remove('yay'); }, 2200); } pb.textContent = '🚀 لنبدا التعلم'; pb.classList.add('flame'); };
  pb.onclick = function(){ if (done) return close(); cur = -1; au.currentTime = 0; var pr = au.play(); if (pr && pr.catch) pr.catch(function(){ toast('اضغط مرة اخرى للاستماع'); }); pb.textContent = '🔊 ...'; cancelAnimationFrame(raf); loop(); };
}
