function onboarding(pre){
  if (S.onb || $('.modal')) return;
  var step = 0, data = {name:S.name || '', lvl:null, goal:0}, old = S.xp > 0, steps = old ? [0, 2] : [0, 1, 2];
  if (pre && pre.name != null){ data.name = pre.name; step = steps[1]; }
  var m = modal('<div id="onb"></div>', 'onbcard');
  m.querySelector('.x').onclick = function(){ S.onb = 1; save(); m.remove(); };
  function dotsH(){ return '<div class="onb-dots">' + steps.map(function(i){ return '<i class="' + (i === step ? 'on' : '') + '"></i>'; }).join('') + '</div>'; }
  function draw(){
    var b = $('#onb', m);
    if (step === 0){
      b.innerHTML = dotsH() + '<div class="big">🚀</div><h3>أهلا بك في Sprachrakete!</h3><p>' + (old ? 'أضفنا ميزات جديدة! ' : 'رحلتك لتعلم الألمانية تبدا الآن. ') + 'ما اسمك؟</p>' +
        '<input class="inp" id="onbName" placeholder="اكتب اسمك" value="' + esc(data.name) + '" autocomplete="given-name"><button class="btn wide" id="onbNext" style="margin-top:12px">التالي</button><button class="btn alt wide" id="onbSkip" style="margin-top:8px">تخط</button>' + (old ? '' : '<button class="linkbtn" id="onbAcct">☁️ لديك حساب؟ سجل الدخول واسترجع تقدمك</button><button class="linkbtn" id="onbRestore" style="margin-top:4px">💾 لديك كود تقدم من جهاز آخر؟ استرجعه</button>');
      $('#onbNext', m).onclick = function(){ data.name = $('#onbName', m).value.trim(); step = steps[1]; draw(); };
      $('#onbSkip', m).onclick = function(){ step = steps[1]; draw(); };
      var rb = $('#onbRestore', m); if (rb) rb.onclick = function(){ m.remove(); backupSheet(); };
      var ab = $('#onbAcct', m); if (ab) ab.onclick = function(){ S.onb = 1; save(); m.remove(); acctSheet(); };
      $('#onbName', m).onkeydown = function(e){ if (e.key === 'Enter') $('#onbNext', m).click(); };
      setTimeout(function(){ var i = $('#onbName', m); if (i) i.focus(); }, 80);
    } else if (step === 1){
      b.innerHTML = dotsH() + '<div class="big">🧭</div><h3>' + (data.name ? 'تشرفنا يا ' + esc(data.name) + '! ' : '') + 'ما مستواك في الألمانية؟</h3>' +
        '<div class="onb-opts"><button class="onb-o" data-l="new"><span>🌱</span><b>مبتدئ تماما</b><small>ابدأ من الحروف والأرقام</small></button>' +
        '<button class="onb-o" data-l="some"><span>📘</span><b>أعرف القليل</b><small>ابدأ بدروس A1</small></button>' +
        '<button class="onb-o" data-l="test"><span>❓</span><b>لا أعرف</b><small>اختبار قصير يحدد مستواي</small></button></div>';
      $$('.onb-o', m).forEach(function(o){ o.onclick = function(){ data.lvl = o.dataset.l; step = 2; draw(); }; });
    } else {
      b.innerHTML = dotsH() + '<div class="big">🎯</div><h3>' + (old && data.name ? 'أهلا يا ' + esc(data.name) + '! ' : '') + 'كم تريد أن تتعلم كل يوم؟</h3><p>اختر هدفا يوميا ويمكنك تغييره لاحقا من حسابي.</p>' +
        '<div class="onb-opts">' + GOALS.map(function(g){ return '<button class="onb-o' + (g.x === data.goal ? ' on' : '') + '" data-g="' + g.x + '"><span>⏱️</span><b>' + g.t + '</b><small>' + g.d + ' · ' + g.x + ' نقطة يوميا</small></button>'; }).join('') + '</div>' +
        '<button class="btn wide flame" id="onbGo" style="margin-top:12px"' + (data.goal ? '' : ' disabled') + '>🚀 لنبدا</button>';
      $$('.onb-o', m).forEach(function(o){ o.onclick = function(){ data.goal = +o.dataset.g; $$('.onb-o', m).forEach(function(z){ z.classList.toggle('on', z === o); }); $('#onbGo', m).disabled = false; }; });
      $('#onbGo', m).onclick = function(){
        if (!data.goal) return;
        if (data.name) S.name = data.name; S.goal = data.goal; S.onb = 1; save(); m.remove();
        setTimeout(waInvite, 700);
        if (!data.lvl){ viewHome(); toast('🎯 هدفك اليومي: ' + S.goal + ' نقطة'); return; }
        go(data.lvl === 'test' ? '#/test' : data.lvl === 'some' ? '#/learn/a1' : '#/words');
      };
    }
  }
  draw();
}

