var TUTOR_URL = 'https://tutor.mound379.workers.dev';
var TUT_SCENES = [['free', 'حديث حر', '💬'], ['meet', 'التعارف', '👋'], ['cafe', 'في المقهى', '☕'], ['shop', 'التسوق', '🛒'], ['work', 'العمل', '💼']];
var TUT = null;
function tutUrl(){ return String(CFG.tutor || TUTOR_URL).replace(/\/+$/, ''); }
function tutApi(path, body){
  return fetch(tutUrl() + path, {method:body ? 'POST' : 'GET', headers:{'Content-Type':'application/json', Authorization:'Bearer ' + (AUTH ? AUTH.token : '')}, body:body ? JSON.stringify(body) : undefined})
    .then(function(r){ return r.json().catch(function(){ return {}; }).then(function(j){ if (!r.ok){ var e = new Error(j.error || 'تعذر الاتصال بلينا الآن'); e.j = j; e.st = r.status; throw e; } return j; }); }, function(){ throw new Error('تعذر الاتصال بلينا. تأكد من الإنترنت'); });
}
function tutStop(){ var t = TUT; if (!t) return; t.live = false; clearTimeout(t.tm); clearInterval(t.iv);
  try{ if (t.rec && t.rec.state !== 'inactive') t.rec.stop(); }catch(e){} try{ if (t.stream) t.stream.getTracks().forEach(function(x){ x.stop(); }); }catch(e){}
  try{ if (t.ctx) t.ctx.close(); }catch(e){} try{ if (window.speechSynthesis) speechSynthesis.cancel(); }catch(e){} TUT = null; }
window.addEventListener('hashchange', function(){ if (TUT && !/^#\/tutor/.test(location.hash)) tutStop(); });
function tutVoice(){ var v = (window.speechSynthesis && speechSynthesis.getVoices()) || [], de = v.filter(function(x){ return /^de(-|_|$)/i.test(x.lang); });
  return de.find(function(x){ return /anna|petra|helena|katja|marlene|vicki|female|frau/i.test(x.name); }) || de.find(function(x){ return /google/i.test(x.name); }) || de[0] || null; }
function tutSay(text, done){ var t = TUT; if (!t || !window.speechSynthesis || !window.SpeechSynthesisUtterance){ setTimeout(done, 600); return; }
  try{ speechSynthesis.cancel(); var u = new SpeechSynthesisUtterance(text), v = tutVoice(); u.lang = 'de-DE'; if (v) u.voice = v; u.rate = t.level === 'A1' ? 0.9 : 0.97;
    var fin = false, end = function(){ if (fin) return; fin = true; clearTimeout(g); done(); }, g = setTimeout(end, Math.max(4000, text.length * 110));
    u.onend = end; u.onerror = end; speechSynthesis.speak(u); }catch(e){ setTimeout(done, 600); } }
