    (it.conj ? '<span class="cj">' + esc(it.conj) + '</span>' : '') + '</span>' + iActs(it) + '<span class="play sm" aria-hidden="true">' + ICON_PLAY + '</span>' + (it.u != null && S.heard[it.u] && S.heard[it.u][it.k] ? '<span class="hd">✓</span>' : '') + '</button>';
