  if (done && !(S.wk && S.wk[wk])){ S.wk = S.wk || {}; S.wk[wk] = 1; save(); setTimeout(function(){ toast('🏆 أنجزت تحدي الأسبوع!'); confetti(); checkBadges(); }, 600); }
