  var inp = $('#clsCode'), err = $('#clsErr'), cells = $$('.crcode .ob'), busy = false;
  var paint = function(){ var v = inp.value; cells.forEach(function(c, i){ c.textContent = v[i] || ''; c.classList.toggle('full', !!v[i]); c.classList.toggle('on', document.activeElement === inp && i === Math.min(v.length, 5)); }); };
  inp.oninput = function(){ inp.value = inp.value.toUpperCase().replace(/[^A-Z0-9]/g, '').slice(0, 6); err.hidden = true; paint(); if (inp.value.length === 6) join(); };
  inp.onfocus = inp.onblur = paint; paint();
